import{_ as t,o as e,c as r,ag as d}from"./chunks/framework.DMXcdKmJ.js";const u=JSON.parse('{"title":"确认安装成功","description":"通过安装结果、管理入口、组织登录和退出检查，确认中心已具备基本使用条件。","frontmatter":{"title":"确认安装成功","description":"通过安装结果、管理入口、组织登录和退出检查，确认中心已具备基本使用条件。","status":"reviewed","kind":"how-to"},"headers":[],"relativePath":"zh/installation/verify.md","filePath":"zh/安装运维/确认安装成功.md"}'),i={name:"zh/installation/verify.md"};function l(h,a,o,n,s,c){return e(),r("div",null,[...a[0]||(a[0]=[d('<h1 id="确认安装成功" tabindex="-1">确认安装成功 <a class="header-anchor" href="#确认安装成功" aria-label="Permalink to &quot;确认安装成功&quot;">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>确认中心安装命令成功结束，平台管理入口和组织工作台能够使用，并完成一次登录、页面访问、刷新与退出检查。</p><p>这些检查确认中心的安装和基本访问。采集、计算、报警、历史数据及实际工程运行需要按业务另行验收。</p><h2 id="角色与环境前提" tabindex="-1">角色与环境前提 <a class="header-anchor" href="#角色与环境前提" aria-label="Permalink to &quot;角色与环境前提&quot;">​</a></h2><p>安装人员核对终端结果，平台超级管理员核对管理入口，组织管理员核对公共入口。准备安装结果中的两个地址，以及各自对应的账号。</p><p>全新安装应先完成<a href="/induframe-docs/zh/installation/first-setup.html">完成首次设置</a>。保留数据重新安装时，应准备原平台和原组织的管理员账号。</p><h2 id="操作入口" tabindex="-1">操作入口 <a class="header-anchor" href="#操作入口" aria-label="Permalink to &quot;操作入口&quot;">​</a></h2><p>使用安装时的终端记录，以及安装结果给出的管理入口和公共入口。浏览器应位于能够访问相应入口的网络中；自签名证书由维护人员先核对并建立信任。</p><h2 id="检查步骤与字段" tabindex="-1">检查步骤与字段 <a class="header-anchor" href="#检查步骤与字段" aria-label="Permalink to &quot;检查步骤与字段&quot;">​</a></h2><h3 id="_1-核对终端结果" tabindex="-1">1. 核对终端结果 <a class="header-anchor" href="#_1-核对终端结果" aria-label="Permalink to &quot;1. 核对终端结果&quot;">​</a></h3><table tabindex="0"><thead><tr><th>检查项</th><th>应看到的结果</th></tr></thead><tbody><tr><td>安装阶段</td><td>完整的 14 个阶段均完成，最后一个为“检查服务状态”</td></tr><tr><td>完成提示</td><td>“InduFrame 中心安装完成。”</td></tr><tr><td>命令结束</td><td>安装命令正常结束，退出状态为 <code>0</code></td></tr><tr><td>交接信息</td><td>公共入口、管理入口、安装日志路径均已记录</td></tr></tbody></table><p>三项安装完成条件必须同时成立。只看到“14/14”或某一页面能访问，不足以判断整个安装已完成。</p><h3 id="_2-核对平台管理入口" tabindex="-1">2. 核对平台管理入口 <a class="header-anchor" href="#_2-核对平台管理入口" aria-label="Permalink to &quot;2. 核对平台管理入口&quot;">​</a></h3><ol><li>打开终端给出的管理入口，确认标题为“平台管理员登录”。</li><li>在“账号”和“密码”中填写平台超级管理员信息，点击“登录”。</li><li>确认可以打开“组织管理”，看到默认组织 InduFrame。</li><li>全新安装确认已按<a href="/induframe-docs/zh/installation/first-setup.html">完成首次设置</a>重置默认组织管理员密码。</li></ol><p>正常全新安装的平台超级管理员使用安装时设置的密码；保留数据重新安装的平台使用原有密码。</p><h3 id="_3-核对公共入口和工作台" tabindex="-1">3. 核对公共入口和工作台 <a class="header-anchor" href="#_3-核对公共入口和工作台" aria-label="Permalink to &quot;3. 核对公共入口和工作台&quot;">​</a></h3><ol><li>打开终端给出的公共入口，确认标题为“登录工作台”。</li><li>出现“选择组织”时，选择要检查的组织；仅有一个可登录组织时无需手动选择。</li><li>填写该组织管理员的“账号”和“密码”，点击“登录”。</li><li>打开“工程管理”，确认页面正常显示。新组织没有工程时，可以显示空列表。</li><li>刷新页面，确认仍能正常访问，没有持续加载或错误提示。</li></ol><p>保留数据重装时，应检查原组织名称和原有账号是否符合预期。能登录原组织只确认了账号与组织访问，不能代替原有业务数据及业务功能的逐项检查。</p><h3 id="_4-核对退出登录" tabindex="-1">4. 核对退出登录 <a class="header-anchor" href="#_4-核对退出登录" aria-label="Permalink to &quot;4. 核对退出登录&quot;">​</a></h3><p>在侧栏账号菜单选择“登出”，在“确定要登出吗？”提示中点击“确定”。确认返回登录页。</p><p>再次打开刚才的工程管理页面，应要求重新登录，不能继续看到受保护的页面内容。</p><h3 id="_5-保存交接信息" tabindex="-1">5. 保存交接信息 <a class="header-anchor" href="#_5-保存交接信息" aria-label="Permalink to &quot;5. 保存交接信息&quot;">​</a></h3><table tabindex="0"><thead><tr><th>信息</th><th>保存内容</th></tr></thead><tbody><tr><td>安装包</td><td>完整原包及其交付版本</td></tr><tr><td>入口</td><td>公共入口、管理入口的完整地址</td></tr><tr><td>管理责任</td><td>平台管理员、组织管理员及服务器维护人员</td></tr><tr><td>操作记录</td><td>安装时间、本次日志路径、检查结果及未通过的项目</td></tr><tr><td>证书</td><td>证书维护责任人及浏览器信任处理结果</td></tr></tbody></table><p>账号密码按交接约定单独保管，不要附在问题截图或普通检查记录中。</p><h2 id="成功确认" tabindex="-1">成功确认 <a class="header-anchor" href="#成功确认" aria-label="Permalink to &quot;成功确认&quot;">​</a></h2><p>安装终端结果、平台管理入口、组织登录、工程管理访问、刷新和退出检查均符合上述预期，才完成本页的中心安装确认。</p><p>本指南的安装检查以 Linux amd64 专用虚拟机上的自签名证书安装为基础。再次运行当前完整包时，应先按终端选择更新或取消；取消后命令正常结束只表示已取消，不能作为更新成功的证明。更新、正常重启及原服务器保留数据重装后，均应重新核对入口和原组织登录。更换系统、架构、证书方式或恢复完整业务，需要分别确认适用条件和结果。</p><h2 id="检查未通过时" tabindex="-1">检查未通过时 <a class="header-anchor" href="#检查未通过时" aria-label="Permalink to &quot;检查未通过时&quot;">​</a></h2><p>停在未通过的项目，记录访问入口、页面标题、操作时间和具体提示。终端未成功结束时，不继续浏览器首次设置；浏览器访问失败时，不把它直接判断为需要卸载或删除数据。</p><p>先按<a href="/induframe-docs/zh/installation/troubleshooting.html">安装常见问题</a>检查可观察条件，再交给维护人员处理。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><p>将入口与账号交给对应使用者，按<a href="/induframe-docs/zh/guide/login.html">登录与退出</a>开始日常使用。需要查看完整入门顺序，可返回<a href="/induframe-docs/zh/start/">快速开始</a>。</p>',33)])])}const b=t(i,[["render",l]]);export{u as __pageData,b as default};
